CREATE TABLE oracle_module_installations(digest TEXT PRIMARY KEY,module TEXT NOT NULL,package TEXT NOT NULL,UNIQUE(module,digest));
CREATE TABLE oracle_module_desired(module TEXT PRIMARY KEY,digest TEXT NOT NULL,loaded BIGINT NOT NULL CHECK(loaded IN(0,1)),FOREIGN KEY(module,digest) REFERENCES oracle_module_installations(module,digest));
CREATE TABLE oracle_module_activations(module TEXT NOT NULL,guild TEXT NOT NULL,active BIGINT NOT NULL CHECK(active IN(0,1)),grants TEXT NOT NULL,bindings TEXT NOT NULL,PRIMARY KEY(module,guild),FOREIGN KEY(guild) REFERENCES oracle_guilds(id));
CREATE TABLE oracle_module_namespaces(module TEXT NOT NULL,guild TEXT NOT NULL,data_version BIGINT NOT NULL CHECK(data_version>=0),target_version BIGINT,artifact_digest TEXT,cursor TEXT,last_collection TEXT COLLATE "C" NOT NULL DEFAULT '',last_key TEXT COLLATE "C" NOT NULL DEFAULT '',PRIMARY KEY(module,guild),CHECK((target_version IS NULL AND artifact_digest IS NULL) OR (target_version>data_version AND artifact_digest IS NOT NULL)));
CREATE TABLE oracle_module_documents(module TEXT NOT NULL,guild TEXT NOT NULL,collection TEXT COLLATE "C" NOT NULL,key TEXT COLLATE "C" NOT NULL,value TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),data_version BIGINT NOT NULL,PRIMARY KEY(module,guild,collection,key),FOREIGN KEY(module,guild) REFERENCES oracle_module_namespaces(module,guild));
CREATE INDEX oracle_module_migration_scan ON oracle_module_documents(module,guild,data_version,collection,key);
CREATE TABLE oracle_module_migration_pages(module TEXT NOT NULL,guild TEXT NOT NULL,digest TEXT NOT NULL,expected_cursor TEXT,next_cursor TEXT,last_collection TEXT COLLATE "C" NOT NULL,last_key TEXT COLLATE "C" NOT NULL,finished BIGINT NOT NULL CHECK(finished IN(0,1)),readset TEXT NOT NULL,PRIMARY KEY(module,guild),FOREIGN KEY(module,guild) REFERENCES oracle_module_namespaces(module,guild));
